{
  "edges": {
    "Triggers__Maladaptive_Strategies": {
      "weight": 6,
      "explanation": "The vignette implies that when he encounters reminders he tries to regain control, and elsewhere describes coping responses of constant mental occupation, looking down, and withdrawal.",
      "quote": "When confronted with these reminders, he becomes sharply on edge and struggles to regain a sense of control."
    },
    "Triggers__Threat": {
      "weight": 10,
      "explanation": "The text explicitly states that reminders make him feel acutely on edge, indicating triggers directly produce a sense of current danger.",
      "quote": "When confronted with these reminders, he becomes sharply on edge"
    },
    "Triggers__Memory": {
      "weight": 0,
      "explanation": "Although reminders are described, the vignette does not state that they evoke intrusive trauma memories or recollections.",
      "quote": ""
    },
    "Triggers__Negative_Appraisals": {
      "weight": 10,
      "explanation": "The vignette explicitly says these reminder situations intensify his beliefs that others are unsafe and that something is wrong with him.",
      "quote": "The same moments also intensify his sense that other people are unsafe and unknowable, while reinforcing his belief that there is something wrong with him"
    },
    "Negative_Appraisals__Maladaptive_Strategies": {
      "weight": 10,
      "explanation": "The text directly states that his beliefs about being damaged, separate, and unable to know who may harm him lead him to cope through distraction, looking down, and withdrawal.",
      "quote": "Believing that he is damaged, separate from others, and unable to know who may harm him, he copes by keeping his mind occupied constantly, often looking down and withdrawing"
    },
    "Negative_Appraisals__Threat": {
      "weight": 8,
      "explanation": "His beliefs about others being unpredictable and harmful are presented as shaping a life organized around persistent danger.",
      "quote": "he speaks with conviction about a world in which “you can never know who will harm you.” These beliefs now shape much of how he moves through university life and social situations."
    },
    "Negative_Appraisals__Memory": {
      "weight": 0,
      "explanation": "The vignette does not indicate that his negative beliefs directly trigger or intensify trauma memories.",
      "quote": ""
    },
    "Negative_Appraisals__Triggers": {
      "weight": 0,
      "explanation": "There is no evidence that his appraisals create or increase exposure to triggers themselves.",
      "quote": ""
    },
    "Memory__Maladaptive_Strategies": {
      "weight": 0,
      "explanation": "Rumination about the trauma is described, but the vignette does not show trauma memory causing other maladaptive strategies.",
      "quote": ""
    },
    "Memory__Threat": {
      "weight": 0,
      "explanation": "The vignette does not explicitly describe trauma memories producing a sense of current threat.",
      "quote": ""
    },
    "Memory__Negative_Appraisals": {
      "weight": 0,
      "explanation": "There is no direct statement that trauma memories generate his negative beliefs about himself or others.",
      "quote": ""
    },
    "Memory__Triggers": {
      "weight": 0,
      "explanation": "The text does not suggest trauma memory creates or heightens triggers.",
      "quote": ""
    },
    "Threat__Maladaptive_Strategies": {
      "weight": 6,
      "explanation": "His life is described as organized around persistent danger and disconnection, and he copes with distraction and withdrawal, implying threat contributes to these strategies.",
      "quote": "Since the event, his daily life has become organized around a persistent sense of danger and disconnection."
    },
    "Threat__Memory": {
      "weight": 0,
      "explanation": "The vignette does not state that feeling threatened causes trauma memories or recollections.",
      "quote": ""
    },
    "Threat__Negative_Appraisals": {
      "weight": 4,
      "explanation": "Threat and negative beliefs co-occur closely in the description of his post-traumatic life, but the direction from threat to appraisal is not stated.",
      "quote": "Since the event, his daily life has become organized around a persistent sense of danger and disconnection. He describes feeling set apart from other people, as though something about him has been permanently altered"
    },
    "Threat__Triggers": {
      "weight": 0,
      "explanation": "There is no evidence that his sense of current danger produces or increases triggers.",
      "quote": ""
    },
    "Maladaptive_Strategies__Memory": {
      "weight": 6,
      "explanation": "The vignette implies that rumination, seeking out associated people, and going near the trauma location keep him tied to the trauma.",
      "quote": "These patterns appear to keep him emotionally tied to the trauma"
    },
    "Maladaptive_Strategies__Negative_Appraisals": {
      "weight": 6,
      "explanation": "These coping patterns are said to worsen his sense of safety, which implies they help maintain his negative views of danger and vulnerability.",
      "quote": "These patterns appear to keep him emotionally tied to the trauma and have taken a toll on his relationships, his sense of safety"
    }
  }
}
